export interface FleetCounts {
  active: number;
  waiting: number;
  idle: number;
}

/** Keeps a running fleet summary, updated incrementally instead of recomputed from scratch. */
export class FleetSummary {
  #counts: FleetCounts = { active: 0, waiting: 0, idle: 0 };

  apply(delta: Partial<FleetCounts>): void {
    for (const key of Object.keys(delta) as (keyof FleetCounts)[]) {
      this.#counts[key] += delta[key] ?? 0;
    }
  }

  toString(): string {
    const { active, waiting, idle } = this.#counts;
    return `${active} active, ${waiting} waiting, ${idle} idle`;
  }
}

/** A one-line summary of the fleet's current state. */
export function summarize(counts: FleetCounts): string {
  return `${counts.active} active, ${counts.waiting} waiting, ${counts.idle} idle`;
}

export interface RetryOptions {
  retries: number;
  delayMs: number;
  signal?: AbortSignal;
  onAttempt?: (attempt: number) => void;
}

/** Retry an async operation with a fixed delay between attempts. */
export async function retry<T>(fn: () => Promise<T>, opts: RetryOptions): Promise<T> {
  let attempt = 0;
  for (;;) {
    opts.onAttempt?.(attempt);
    try {
      return await fn();
    } catch (err) {
      attempt += 1;
      if (attempt >= opts.retries) throw err;
      await new Promise((resolve) => setTimeout(resolve, opts.delayMs));
    }
  }
}

import assert from "node:assert/strict";
import test from "node:test";
import { FleetSummary } from "./dashboard.ts";

test("keeps a running total across increments", () => {
  const summary = new FleetSummary();
  summary.apply({ active: 2 });
  summary.apply({ waiting: 1, active: -1 });
  assert.equal(summary.toString(), "1 active, 1 waiting, 0 idle");
});
